// App.js
import React, { useEffect, useRef, useState } from 'react';
import { Moon, Sun } from 'lucide-react';
import Lottie from 'lottie-react';
import codingAnimation from './coding.json';

const fullLines = [
  'name = "Chetanya Makkar"',
  'major = "Computer Science"',
  'minor = "Computational Finance"',
  'gpa = 3.76',
  'school = "University of Maryland"',
];

const sections = ['About', 'Skills', 'Projects', 'Experience', 'Contact'];

export default function App() {
  const [typedLines, setTypedLines] = useState([]);
  const [currentLine, setCurrentLine] = useState('');
  const [lineIndex, setLineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [loop, setLoop] = useState(0);
  const [activeSection, setActiveSection] = useState('About');
  const [darkMode, setDarkMode] = useState(true);
  const refs = useRef({});

  const highlightPartial = (line) => {
    const [left, rightRaw] = line.split('=');
    const variable = left?.trim();
    const right = rightRaw?.trim();

    return (
      <>
        <span className={darkMode ? "text-[#9CDCFE]" : "text-[#0000FF]"}>{variable}</span>
        <span className={darkMode ? "text-[#d4d4d4]" : "text-[#000000]"}> = </span>
        {right ? (
          right.startsWith('"') ? (
            <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>{right}</span>
          ) : (
            <span className={darkMode ? "text-[#b5cea8]" : "text-[#098658]"}>{right}</span>
          )
        ) : null}
      </>
    );
  };

  const highlightLine = (line) => {
    const [left, right] = line.split('=');
    const variable = left?.trim();
    const value = right?.trim();

    return (
      <>
        <span className={darkMode ? "text-[#9CDCFE]" : "text-[#0000FF]"}>{variable}</span>
        <span className={darkMode ? "text-[#d4d4d4]" : "text-[#000000]"}> = </span>
        {value?.startsWith('"') ? (
          <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>{value}</span>
        ) : (
          <span className={darkMode ? "text-[#b5cea8]" : "text-[#098658]"}>{value}</span>
        )}
      </>
    );
  };

  useEffect(() => {
    if (lineIndex < fullLines.length) {
      if (charIndex < fullLines[lineIndex].length) {
        const timeout = setTimeout(() => {
          setCurrentLine(prev => prev + fullLines[lineIndex][charIndex]);
          setCharIndex(i => i + 1);
        }, 40);
        return () => clearTimeout(timeout);
      } else {
        const timeout = setTimeout(() => {
          setTypedLines(prev => [...prev, fullLines[lineIndex]]);
          setCurrentLine('');
          setCharIndex(0);
          setLineIndex(i => i + 1);
        }, 300);
        return () => clearTimeout(timeout);
      }
    } else {
      const timeout = setTimeout(() => {
        setTypedLines([]);
        setCurrentLine('');
        setCharIndex(0);
        setLineIndex(0);
        setLoop(l => l + 1);
      }, 3000);
      return () => clearTimeout(timeout);
    }
  }, [charIndex, lineIndex, loop]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { 
        threshold: 0.5,
        rootMargin: '-20% 0px -20% 0px' // This creates a smaller intersection area in the middle of the viewport
      }
    );

    // Observe all sections
    sections.forEach(sec => {
      const element = document.getElementById(sec);
      if (element) observer.observe(element);
    });

    return () => observer.disconnect();
  }, []);

  const bgClass = darkMode ? 'bg-[#1e1e1e] text-[#d4d4d4]' : 'bg-[#ffffff] text-[#000000]';
  const sidebarClass = darkMode ? 'bg-[#252526]' : 'bg-[#f3f3f3]';
  const headingColor = darkMode ? 'text-[#4FC1FF]' : 'text-[#0000FF]';
  const linkColor = darkMode ? 'text-blue-400' : 'text-[#0000FF]';
  const hoverLinkColor = darkMode ? 'hover:text-blue-300' : 'hover:text-[#0000FF]/80';
  const strongColor = darkMode ? 'text-[#9CDCFE]' : 'text-[#0000FF]';
  const textColor = darkMode ? 'text-[#d4d4d4]' : 'text-[#000000]';

  return (
    <div className={`relative flex ${bgClass} font-mono text-base`}>
      {/* Theme toggle button in top-right corner */}
      <button
        onClick={() => setDarkMode(!darkMode)}
        className={`fixed top-4 right-4 z-50 p-2 rounded-full border ${
          darkMode ? 'hover:bg-gray-400 hover:text-white' : 'hover:bg-gray-200'
        }`}
      >
        {darkMode ? <Sun size={18} /> : <Moon size={18} />}
      </button>

      {/* Sidebar */}
      <div className={`fixed top-0 left-0 h-screen w-24 ${sidebarClass} flex flex-col items-center space-y-4 py-6 z-40`}>
        {sections.map(sec => (
          <a
            key={sec}
            href={`#${sec}`}
            onClick={(e) => {
              e.preventDefault();
              document.getElementById(sec).scrollIntoView({ behavior: 'smooth' });
              setActiveSection(sec);
            }}
            className={`text-xs writing-vertical tracking-wide transition-all duration-200 cursor-pointer ${
              darkMode ? 'hover:text-blue-400' : 'hover:text-[#0000FF]'
            } ${
              activeSection === sec 
                ? darkMode 
                  ? 'text-blue-500 font-bold scale-110' 
                  : 'text-[#0000FF] font-bold scale-110'
                : darkMode 
                  ? 'text-gray-400' 
                  : 'text-gray-600'
            }`}
            style={{ writingMode: 'vertical-rl', transform: 'rotate(270deg)' }}
          >
            {sec}
          </a>
        ))}
      </div>

      {/* Main content */}
      <div className="ml-24 flex-1 p-6">
        <div className="max-w-6xl mx-auto">
          <section id="About" ref={el => (refs.current['About'] = el)} className="py-16 flex items-center justify-center">
            <div className="flex flex-col lg:flex-row items-center justify-center gap-8 w-full max-w-4xl mx-auto">
              <div className="space-y-2 text-center lg:text-left flex-1">
                {typedLines.map((line, idx) => (
                  <div key={`done-${loop}-${idx}`} className="whitespace-pre">{highlightLine(line)}</div>
                ))}
                {lineIndex < fullLines.length && (
                  <div className="whitespace-pre">
                    {highlightPartial(currentLine)}
                    <span className="border-r-2 border-gray-400 animate-blink">&nbsp;</span>
                  </div>
                )}
              </div>
              <div className="flex-1 hidden lg:block">
                <Lottie animationData={codingAnimation} loop={true} />
              </div>
            </div>
          </section>

          <div className="h-24"></div> {/* Spacer between About and Skills */}

          <section id="Skills" ref={el => (refs.current['Skills'] = el)} className="py-16 flex items-center">
            <div className="w-full">
              <h1 className={`text-2xl mb-10 ${headingColor} text-center`}>Skills</h1>
              <div className="space-y-10 max-w-4xl mx-auto">
                <div className="text-center">
                  <h2 className={`text-lg font-semibold ${headingColor} mb-4`}>💻 Technical</h2>
                  <div className="space-y-2">
                    <p className="text-sm">
                      <span className={strongColor}>languages</span> = 
                      <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>["Python", "Java", "C", "OCaml", "SQL", "JavaScript"]</span>
                    </p>
                    <p className="text-sm">
                      <span className={strongColor}>frameworks</span> = 
                      <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>["React", "Tailwind", "Node.js", "Scikit-learn"]</span>
                    </p>
                  </div>
                </div>

                <div className="text-center">
                  <h2 className={`text-lg font-semibold ${headingColor} mb-4`}>⚙️ Tools</h2>
                  <div className="space-y-2">
                    <p className="text-sm">
                      <span className={strongColor}>tools</span> = 
                      <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>["Git", "Jupyter", "Excel", "PowerPoint", "VS Code"]</span>
                    </p>
                  </div>
                </div>

                <div className="text-center">
                  <h2 className={`text-lg font-semibold ${headingColor} mb-4`}>📈 Finance / Data</h2>
                  <div className="space-y-2">
                    <p className="text-sm">
                      <span className={strongColor}>finance_skills</span> = 
                      <span className={darkMode ? "text-[#ce9178]" : "text-[#A31515]"}>["Portfolio Optimization", "Regression", "Backtesting", "A/B Testing"]</span>
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <section id="Projects" ref={el => (refs.current['Projects'] = el)} className="py-16 flex items-center">
            <div className="w-full">
              <h1 className={`text-2xl mb-10 ${headingColor} text-center`}>Projects</h1>
              <div className="max-w-4xl mx-auto">
                <ul className="space-y-4 text-sm text-center">
                  <li className="flex flex-col items-center">
                    <strong className={`${headingColor} mb-1`}>Flash Crash Analysis</strong>
                    <span className={textColor}>Regression analysis on high-frequency data confirming Welch & Goyal's predictor limits.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className={`${headingColor} mb-1`}>Portfolio Optimization</strong>
                    <span className={textColor}>Used Python and convex optimization to build efficient frontiers.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className={`${headingColor} mb-1`}>OCaml Type Checker</strong>
                    <span className={textColor}>Custom optimizer for OCaml using type inference and syntax trees.</span>
                  </li>
                  <li className="flex flex-col items-center">
                    <strong className={`${headingColor} mb-1`}>Solar Power Story</strong>
                    <span className={textColor}>Visualized Indian solar trends; recognized on Kaggle for storytelling.</span>
                  </li>
                </ul>
              </div>
            </div>
          </section>

          <section id="Experience" ref={el => (refs.current['Experience'] = el)} className="py-16 flex items-center">
            <div className="w-full">
              <h1 className={`text-2xl mb-10 ${headingColor} text-center`}>Experience</h1>
              <div className="max-w-4xl mx-auto">
                <div className="space-y-8 text-sm">
                  <div className="text-center">
                    <h2 className={`text-lg font-semibold ${headingColor} mb-4`}>💼 Professional Experience</h2>
                    <div className="space-y-6">
                      <div className="flex flex-col items-center">
                        <strong className={`${strongColor} mb-2`}>Software Engineering Intern @ BuzzClan</strong>
                        <span className={textColor}>Developed and maintained enterprise applications</span>
                      </div>
                      <div className="flex flex-col items-center">
                        <strong className={`${strongColor} mb-2`}>Researcher @ UMD Climate Lab</strong>
                        <span className={textColor}>Regression & uncertainty modeling for climate data analysis</span>
                      </div>
                    </div>
                  </div>

                  <div className="text-center">
                    <h2 className={`text-lg font-semibold ${headingColor} mb-4`}>👨‍🏫 Teaching & Leadership</h2>
                    <div className="space-y-6">
                      <div className="flex flex-col items-center">
                        <strong className={`${strongColor} mb-2`}>TA for Calculus I & II</strong>
                        <span className={textColor}>Mentored students, designed curriculum, improved outcomes</span>
                      </div>
                      <div className="flex flex-col items-center">
                        <strong className={`${strongColor} mb-2`}>Co-founder @ Ruhin Education</strong>
                        <span className={textColor}>Built edtech platform for special needs students</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          <section id="Contact" ref={el => (refs.current['Contact'] = el)} className="py-16 flex items-center">
            <div className="w-full">
              <h1 className={`text-2xl mb-10 ${headingColor} text-center`}>Contact</h1>
              <div className="max-w-4xl mx-auto">
                <div className="space-y-4 text-sm text-center">
                  <p className="flex flex-col items-center">
                    <span className={`${headingColor} mb-1`}>Email</span>
                    <a href="mailto:chetanyamakkar99@gmail.com" className={`${linkColor} ${hoverLinkColor} transition-colors`}>
                      chetanyamakkar99@gmail.com
                    </a>
                  </p>
                  <p className="flex flex-col items-center">
                    <span className={`${headingColor} mb-1`}>LinkedIn</span>
                    <a href="https://www.linkedin.com/in/chetanyamakkar/" target="_blank" className={`${linkColor} ${hoverLinkColor} transition-colors`}>
                      linkedin.com/in/chetanyamakkar
                    </a>
                  </p>
                  <p className="flex flex-col items-center">
                    <span className={`${headingColor} mb-1`}>GitHub</span>
                    <a href="https://github.com/chetanyamakkar11" target="_blank" className={`${linkColor} ${hoverLinkColor} transition-colors`}>
                      github.com/chetanyamakkar11
                    </a>
                  </p>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}
